package com.tainted.community.web;

import com.tainted.community.error.PostNotFoundException;
import com.tainted.community.service.CommunityService;
import com.tainted.community.web.dto.CommentResponse;
import com.tainted.community.web.dto.CreatePostResponse;
import com.tainted.community.web.dto.LikeResponse;
import com.tainted.community.web.dto.PostResponse;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.WebMvcTest;
import org.springframework.boot.test.mock.mockito.MockBean;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;

import java.util.Arrays;

import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.when;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.content;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

/**
 * CommunityController 슬라이스 테스트(@WebMvcTest + MockMvc). 라우팅·상태코드·직렬화,
 * 그리고 GlobalExceptionHandler 가 실제로 application/problem+json 본문을 내는지 검증한다.
 */
@WebMvcTest(CommunityController.class)
class CommunityControllerTest {

    @Autowired MockMvc mockMvc;

    @MockBean CommunityService communityService;

    @Test
    void createPostReturns201AndPostId() throws Exception {
        when(communityService.createPost(any())).thenReturn(new CreatePostResponse("new-post"));

        mockMvc.perform(post("/internal/posts")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"userId\":\"u\",\"title\":\"t\",\"category\":\"career\","
                                + "\"content\":\"c\",\"moodEmoji\":\"😔\",\"nickname\":\"n\"}"))
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.postId").value("new-post"));
    }

    @Test
    void createPostWithBlankRequiredFieldReturns400ProblemJson() throws Exception {
        mockMvc.perform(post("/internal/posts")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"userId\":\"\",\"title\":\"t\",\"category\":\"career\","
                                + "\"content\":\"c\",\"moodEmoji\":\"😔\",\"nickname\":\"n\"}"))
                .andExpect(status().isBadRequest())
                .andExpect(content().contentTypeCompatibleWith("application/problem+json"))
                .andExpect(jsonPath("$.title").value("Validation failed"))
                .andExpect(jsonPath("$.status").value(400));
    }

    @Test
    void listPostsReturnsArray() throws Exception {
        PostResponse pr = new PostResponse("id-1", "u", "t", "career", "c", "😔", "n", 4,
                "2026-06-20T00:00:00Z");
        when(communityService.listPosts()).thenReturn(Arrays.asList(pr));

        mockMvc.perform(get("/internal/posts"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$[0].id").value("id-1"))
                .andExpect(jsonPath("$[0].likes").value(4));
    }

    @Test
    void getPostReturnsPost() throws Exception {
        PostResponse pr = new PostResponse("id-2", "u", "t", "daily", "c", "🙂", "n", 0,
                "2026-06-20T00:00:00Z");
        when(communityService.getPost("id-2")).thenReturn(pr);

        mockMvc.perform(get("/internal/posts/id-2"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.id").value("id-2"))
                .andExpect(jsonPath("$.category").value("daily"));
    }

    @Test
    void getPostNotFoundReturns404ProblemJson() throws Exception {
        when(communityService.getPost("ghost"))
                .thenThrow(new PostNotFoundException("post not found: ghost"));

        mockMvc.perform(get("/internal/posts/ghost"))
                .andExpect(status().isNotFound())
                .andExpect(content().contentTypeCompatibleWith("application/problem+json"))
                .andExpect(jsonPath("$.type").value("about:blank"))
                .andExpect(jsonPath("$.title").value("Post not found"))
                .andExpect(jsonPath("$.status").value(404))
                .andExpect(jsonPath("$.detail").value("post not found: ghost"));
    }

    @Test
    void addCommentReturns201() throws Exception {
        when(communityService.addComment(eq("id-3"), any()))
                .thenReturn(new CommentResponse("c-1", "id-3", "empathic"));

        mockMvc.perform(post("/internal/posts/id-3/comments")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"author\":\"a\",\"role\":\"empathic\",\"content\":\"text\"}"))
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.commentId").value("c-1"))
                .andExpect(jsonPath("$.role").value("empathic"));
    }

    @Test
    void addCommentWithBlankFieldReturns400() throws Exception {
        mockMvc.perform(post("/internal/posts/id-3/comments")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"author\":\"a\",\"role\":\"\",\"content\":\"text\"}"))
                .andExpect(status().isBadRequest())
                .andExpect(jsonPath("$.status").value(400));
    }

    @Test
    void likeReturns200WithCount() throws Exception {
        when(communityService.like("id-4")).thenReturn(new LikeResponse("id-4", 7));

        mockMvc.perform(post("/internal/posts/id-4/like"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.postId").value("id-4"))
                .andExpect(jsonPath("$.likes").value(7));
    }
}

