                    .body("status", equalTo(404))
                    .body("detail", equalTo("post not found: nimbus-missing-post-404"));
        } finally {
            executeSqlTemplate("sql/post-by-id-get-teardown.sql", p);
        }
    }

    @Test
    void VTC_id_NULL(TestInfo info) {
        // VTC 표준 NULL rule: 경로변수라 완전한 null 재현 불가 → 빈 세그먼트(EMPTY와 동일 관측, docLines 참조)로 근사
        Map<String, String> p = seed(info);
        arrange(p);
        try {
            given().baseUri(BASE_URL)
                    .pathParam("id", "")
            .when()
                    .get("/internal/posts/{id}")
            .then()
                    .statusCode(200);;
        } finally {
            executeSqlTemplate("sql/post-by-id-get-teardown.sql", p);
        }
    }

    @Test
    void VTC_id_EMPTY(TestInfo info) {
        // VTC 표준 EMPTY rule: id 빈 문자열 → 빈 경로 세그먼트, listPosts로 라우팅되어 200 (graphrag 참고 테스트로 검증됨)
        Map<String, String> p = seed(info);
        arrange(p);
        try {
            given().baseUri(BASE_URL)
                    .pathParam("id", "")
            .when()
                    .get("/internal/posts/{id}")
            .then()
                    .statusCode(200);;
        } finally {
            executeSqlTemplate("sql/post-by-id-get-teardown.sql", p);
        }
    }

    @Test
    void VTC_id_WHITE_SPACE(TestInfo info) {
        // VTC 표준 WHITE_SPACE rule(DB_WHERE): 공백 id → trim 없이 그대로 조회 조건 사용 → DB 미스 → 404
        Map<String, String> p = seed(info);
        arrange(p);
        try {
            given().baseUri(BASE_URL)
                    .pathParam("id", " ")
            .when()
                    .get("/internal/posts/{id}")
            .then()
                    .statusCode(404)
                    .body("type", equalTo("about:blank"))
                    .body("title", equalTo("Post not found"))
                    .body("status", equalTo(404))
                    .body("detail", equalTo("post not found:  "));
        } finally {
            executeSqlTemplate("sql/post-by-id-get-teardown.sql", p);
        }
    }

    @Test
    void VTC_id_SPECIAL_CHAR(TestInfo info) {
        // VTC 표준 SPECIAL_CHAR rule(DB_WHERE): SQL injection 문자열 → JPA PreparedStatement 파라미터 바인딩으로 안전 처리 → 404, 부가 행 미생성 확인
        Map<String, String> p = seed(info);
        arrange(p);
        try {
            given().baseUri(BASE_URL)
                    .pathParam("id", "nimbus' OR '1'='1")
            .when()
                    .get("/internal/posts/{id}")
            .then()
                    .statusCode(404)
                    .body("type", equalTo("about:blank"))
                    .body("title", equalTo("Post not found"))
                    .body("status", equalTo(404))
                    .body("detail", equalTo("post not found: nimbus' OR '1'='1"));
            org.junit.jupiter.api.Assertions.assertEquals("0", queryScalar("SELECT COUNT(*) FROM post WHERE id = ?", "nimbus' OR '1'='1"));
        } finally {
            executeSqlTemplate("sql/post-by-id-get-teardown.sql", p);
        }
    }
}

